package greeter

import "strings"

// Slug 把名字转成 URL 友好的锚点 slug：大小写折叠、空白折成连字符、首尾不留。
// 空与纯空白输入返回空串。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"lowercases and hyphenates spaces", "Ada Lovelace", "ada-lovelace"},
		{"collapses runs and trims", "  Grace   Hopper  ", "grace-hopper"},
		{"folds tabs and newlines", "Alan\tTuring\n", "alan-turing"},
		{"empty stays empty", "", ""},
		{"blank stays empty", "   ", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}
